import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.StringTokenizer;import java.util.Arrays;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));int n = Integer.parseInt(br.readLine().trim());int[] s = new int[n];StringTokenizer st = new StringTokenizer(br.readLine());for (int i = 0; i < n; i++) {s[i] = Integer.parseInt(st.nextToken());}int[] sortedSpeeds = s.clone();Arrays.sort(sortedSpeeds);int[] rank = new int[n];for (int i = 0; i < n; i++) {rank[i] = Arrays.binarySearch(sortedSpeeds, s[i]) + 1;}int maxRank = n;int[][] dp = new int[n + 1][maxRank + 1];for (int i = 0; i <= n; i++) {Arrays.fill(dp[i], -1);}dp[0][0] = 0;int[] last1 = new int[n + 1];int[] last2 = new int[n + 1];Arrays.fill(last1, 1000000001);Arrays.fill(last2, 1000000001);int[][] memo = new int[n + 1][maxRank + 1];for (int i = 0; i <= n; i++) Arrays.fill(memo[i], -1);System.out.println(solve(0, 0, 0, s, n, 1000000001, 1000000001, memo));}private static int solve(int idx, int last1, int last2, int[] s, int n, int v1, int v2, int[][] memo) {if (idx == n) return 0;int v1Idx = (v1 == 1000000001) ? 0 : Arrays.binarySearch(s, v1) + 1;int v2Idx = (v2 == 1000000001) ? 0 : Arrays.binarySearch(s, v2) + 1;if (memo[idx][v1Idx == 0 ? 0 : v1Idx] != -1) return memo[idx][v1Idx == 0 ? 0 : v1Idx];int res1 = (s[idx] <= v1 ? 1 : 0) + solve(idx + 1, idx, last2, s, n, s[idx], v2, memo);int res2 = (s[idx] <= v2 ? 1 : 0) + solve(idx + 1, last1, idx, s, n, v1, s[idx], memo);return memo[idx][v1Idx == 0 ? 0 : v1Idx] = Math.max(res1, res2);}}